#!/usr/bin/env python3
"""Plan/replay only the explicitly selected, recorded CT campaign.

Default is read-only planning. --run delegates sequential bounded groups to the
qualified archived-pin controller. --force is the sole recomputation request.
"""
from __future__ import annotations
import argparse,hashlib,importlib.util,json,math,os,subprocess,sys
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]

class ReplayError(ValueError):pass

def read_json(path):
    try:return json.loads(path.read_text())
    except (OSError,ValueError) as error:raise ReplayError(f'Missing/unreadable required record {path}: {error}') from error

def digest(path):
    h=hashlib.sha256()
    with path.open('rb') as stream:
        for block in iter(lambda:stream.read(1024*1024),b''):h.update(block)
    return h.hexdigest()

def within(root,value):
    value=Path(value)
    path=(value if value.is_absolute() else root/value).resolve()
    if not path.is_relative_to(root):raise ReplayError('Replay record must be inside the copied codex directory: '+str(value))
    return path

def selected_names(selection):
    if not isinstance(selection,dict):raise ReplayError('CT selection must be a JSON object')
    reference=selection.get('reference_case')
    if not isinstance(reference,str) or not reference.startswith('ct'):raise ReplayError('An explicit selected CT reference_case is required; no GLM or priority fallback is used')
    animation=selection.get('animation_case')
    if animation is not None and (not isinstance(animation,str) or not animation.startswith('ct')):raise ReplayError('animation_case must explicitly name a CT case')
    selected=[reference]+([animation] if animation else [])
    for category,pairs in selection.items():
        if not category.endswith('_comparisons'):continue
        if not isinstance(pairs,list):raise ReplayError(category+' must be a list of case pairs')
        for pair in pairs:
            if not isinstance(pair,(list,tuple)) or len(pair)!=2 or not all(isinstance(x,str) for x in pair):raise ReplayError('Malformed case pair in '+category)
            selected.extend(pair)
    for category in ['envelope_cases','comparison_plot_cases']:
        if category not in selection:continue
        values=selection[category]
        if not isinstance(values,list) or not all(isinstance(x,str) for x in values):raise ReplayError(category+' must be a list of case names')
        selected.extend(values)
    selected=list(dict.fromkeys(selected))
    if 'required_case_names' in selection:
        names=selection['required_case_names']
        if not isinstance(names,list) or not names or not all(isinstance(x,str) for x in names):raise ReplayError('required_case_names must be a nonempty explicit list of case names')
        if len(set(names))!=len(names):raise ReplayError('required_case_names contains duplicates')
        missing=[name for name in selected if name not in names]
        if missing:raise ReplayError('required_case_names omits selected comparison, envelope or product cases: '+', '.join(missing))
    else:
        names=selected
    for name in names:
        if not isinstance(name,str) or not name.startswith('ct') or Path(name).name!=name or name in ['.','..']:raise ReplayError('Only explicit local CT case names are accepted: '+str(name))
    return names

def load_controller(root):
    path=root/'scripts/run_ct_simulations.py'
    spec=importlib.util.spec_from_file_location('ct_replay_controller',path)
    if spec is None or spec.loader is None:raise ReplayError('Cannot import archived-pin CT controller')
    module=importlib.util.module_from_spec(spec)
    previous=sys.dont_write_bytecode;sys.dont_write_bytecode=True
    try:spec.loader.exec_module(module)
    finally:sys.dont_write_bytecode=previous
    return module

def inspect_case(root,name,controller,metadata,hash_cache):
    """Read ROOT receipts and canonical helpers only; never materialize a pin."""
    if name not in controller.CASES:raise ReplayError('Case absent from current qualified controller catalogue: '+name)
    folder=root/'results'/name
    paths={key:folder/filename for key,filename in [('selection','code_selection.json'),('usage','runner_usage.json'),('metadata','metadata.json'),('status','candidate_status.json'),('provenance','input_code_provenance.json')]}
    records={key:read_json(path) for key,path in paths.items()}
    cfg_path=folder/'run.cfg';native_path=folder/'athinput.ct'
    if not cfg_path.is_file() or not native_path.is_file():raise ReplayError(name+': matching canonical run.cfg and athinput.ct are required')
    cfg=controller.readcfg(cfg_path);code=records['selection'];usage=records['usage']
    receipt_sha=code.get('code_receipt_sha256','')
    if len(receipt_sha)!=64 or any(c not in '0123456789abcdef' for c in receipt_sha):raise ReplayError(name+': invalid archived receipt SHA')
    pin_dir=root/'solver/athena_ct_pins'/receipt_sha
    receipt_path=pin_dir/'code_receipt.json';receipt=read_json(receipt_path)
    binary=within(root,code.get('binary',''))
    if binary!=pin_dir/'athena' or digest(receipt_path)!=receipt_sha:raise ReplayError(name+': archived pin path/receipt digest disagrees')
    if not binary.is_file() or digest(binary)!=code.get('binary_sha256') or code['binary_sha256']!=receipt.get('executable_sha256'):raise ReplayError(name+': portable archived binary hash disagrees')
    # All recorded input/source paths are ROOT-relative archived copies. Original
